// Parse AI legitimacy check and combine with lead data

const lead = $('Map to Lead Schema').item.json;
const aiResponse = $input.first().json;

let analysis = { is_legitimate: true, confidence: 50, is_fsbo: true };

try {
  const content = aiResponse.choices[0].message.content;
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // If parsing fails, assume legitimate to avoid missing leads
}

return [{
  json: {
    ...lead,
    isLegitimate: analysis.is_legitimate,
    legitimacyConfidence: analysis.confidence,
    isFsbo: analysis.is_fsbo,
    aiReasoning: analysis.reasoning
  }
}];

